    /// <summary>
    /// Changes accent color and background custom emoji for profile of the current user; for Telegram Premium users only
    /// </summary>
    public Task<TdLib.TdApi.Objects.Ok> SetProfileAccentColorAsync(int profileAccentColorId = default, long profileBackgroundCustomEmojiId = default)
    {

           using var activity =  StartCallActivity("SetProfileAccentColorAsync", typeof(SetProfileAccentColor).FullName ?? "SetProfileAccentColorAsync");

           try
           {
             return client.SetProfileAccentColorAsync(profileAccentColorId, profileBackgroundCustomEmojiId);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
